        const result = await this.aiService.runFlow(flow, input);

        // 2. Deduct credits
        await this.deductCreditsUseCase.execute(userId, creditCost);

        // 3. Log the generation
        await this.generationLogRepository.log({
            agentId: toolName,
            userId: userId,
            input: input,
            output: result,
            creditCost: creditCost
        });

        return result;
    }
}

